begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008401','routine-parent@example.invalid'),('00000000-0000-4000-8000-000000008402','routine-other@example.invalid');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000008401','Synthetic','00000000-0000-4000-8000-000000008401'),('10000000-0000-4000-8000-000000008402','Other','00000000-0000-4000-8000-000000008402');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000008401','00000000-0000-4000-8000-000000008401'),('10000000-0000-4000-8000-000000008402','00000000-0000-4000-8000-000000008402');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008401','10000000-0000-4000-8000-000000008401','Synthetic',5);
insert into public.task_templates(id,child_id,family_id,title,stars,starts_on,icon) values('30000000-0000-4000-8000-000000008401','20000000-0000-4000-8000-000000008401','10000000-0000-4000-8000-000000008401','Kitap oku',2,current_date-7,'read-book');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008403','10000000-0000-4000-8000-000000008401','Auto approval',5);
insert into public.task_templates(id,family_id,child_id,title,requires_approval) values('30000000-0000-4000-8000-000000008403','10000000-0000-4000-8000-000000008401','20000000-0000-4000-8000-000000008403','First automatic task',false);
insert into public.badge_definitions(slug,family_id,title_i18n,icon,rule) values('routine-auto-first','10000000-0000-4000-8000-000000008401','{"tr":"İlk görev","en":"First task"}','badge-first-task','{"kind":"first_task"}');
create function pg_temp.t() returns uuid language sql as $$select '30000000-0000-4000-8000-000000008401'::uuid$$;
create function pg_temp.child() returns uuid language sql as $$select '20000000-0000-4000-8000-000000008401'::uuid$$;
create function pg_temp.value(stars int default 5) returns jsonb language sql as $$select jsonb_build_object('title','Birlikte kitap oku','icon','task-custom','stars',stars,'days_of_week',jsonb_build_array(1,2,3,4,5,6,7),'time_of_day','evening','requires_approval',true)$$;
create function pg_temp.c() returns uuid language sql as $$select id from public.task_completions where template_id=pg_temp.t() and due_date=current_date$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008401","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008401","role":"parent"}}',true);
select lives_ok($$select public.complete_task(pg_temp.t(),current_date,'40000000-0000-4000-8000-000000008401',pg_temp.child())$$,'child submits routine');
select is((select task_snapshot->>'title' from public.task_completions where id=pg_temp.c()),'Kitap oku','submission freezes title');
select is((select task_snapshot->>'origin' from public.task_completions where id=pg_temp.c()),'submission','new snapshot provenance explicit');
select is((public.task_routine_history(pg_temp.t())->>'pending')::int,1,'preview reports pending work');
select is((public.change_task_routine('50000000-0000-4000-8000-000000008401',pg_temp.t(),1,'save',pg_temp.value())->>'revision')::int,2,'edit increments revision');
select is((public.change_task_routine('50000000-0000-4000-8000-000000008401',pg_temp.t(),1,'save',pg_temp.value())->>'revision')::int,2,'same request replays result');
select is(jsonb_array_length(public.task_routine_history(pg_temp.t())->'rows'),2,'retry did not duplicate history');
select is(public.task_routine_history(pg_temp.t())->'rows'->0->'before_value'->>'title','Kitap oku','history retains old title');
select is((select task_snapshot->>'stars' from public.task_completions where id=pg_temp.c()),'2','edit does not rewrite pending stars');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),1,'save',pg_temp.value())$$,'P0001','task_routine_changed','stale parent blocked');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),2,'save',pg_temp.value(11))$$,'P0001','task_routine_invalid','star limit enforced');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),2,'save',pg_temp.value()||'{"child_id":"20000000-0000-4000-8000-000000008402"}')$$,'P0001','task_routine_invalid','owner injection blocked');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),2,'save',pg_temp.value()||'{"days_of_week":[]}'::jsonb)$$,'P0001','task_routine_invalid','empty day list rejected');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),2,'save',pg_temp.value()||'{"days_of_week":[1,1]}'::jsonb)$$,'P0001','task_routine_invalid','duplicate days rejected');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),2,'save',pg_temp.value()||'{"days_of_week":[8]}'::jsonb)$$,'P0001','task_routine_invalid','invalid weekday rejected');
select throws_ok($$update public.task_templates set stars=10 where id=pg_temp.t()$$,'42501',null,'direct edit cannot bypass version');
select throws_ok($$delete from public.task_templates where id=pg_temp.t()$$,'42501',null,'routine deletion cannot cascade earned work');
select lives_ok($$select public.review_task(pg_temp.c(),true)$$,'pending work can be approved after settings edit');
select is((select delta from public.star_events where completion_id=pg_temp.c()),2,'approval awards ORIGINAL stars');
select is((select task_snapshot->>'icon' from public.task_completions where id=pg_temp.c()),'read-book','badge evidence retains original category');
select lives_ok($$select public.complete_task(pg_temp.t(),current_date-1,gen_random_uuid(),pg_temp.child())$$,'later submission uses new settings');
select is((select task_snapshot->>'stars' from public.task_completions where template_id=pg_temp.t() and due_date=current_date-1),'5','new submission sees new stars');
select is((public.change_task_routine(gen_random_uuid(),pg_temp.t(),2,'archive')->>'revision')::int,3,'archive versioned');
select is((select active from public.task_templates where id=pg_temp.t()),false,'archived routine inactive');
select lives_ok($$select public.complete_task(pg_temp.t(),current_date,'40000000-0000-4000-8000-000000008401',pg_temp.child())$$,'successful submission replay recoverable after routine archive');
select throws_ok($$select public.complete_task(pg_temp.t(),current_date-2,gen_random_uuid(),pg_temp.child())$$,'P0001','template_inactive','no new submissions on archived routine');
select lives_ok($$select public.review_task((select id from public.task_completions where template_id=pg_temp.t() and due_date=current_date-1),true)$$,'archive does not block pending approval');
select is((select sum(delta)::int from public.star_events where child_id=pg_temp.child()),7,'archive does not revoke earned stars');
select throws_ok($$update public.task_templates set active=true where id=pg_temp.t()$$,'P0001','task_restore_paused','old client cannot resume archive');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),3,'save',pg_temp.value())$$,'P0001','task_routine_archived','cannot edit archive until restored');
select is((public.change_task_routine(gen_random_uuid(),pg_temp.t(),3,'restore')->>'revision')::int,4,'restore versioned');
select is((select active from public.task_templates where id=pg_temp.t()),false,'restore never auto resumes');
select is((public.change_task_routine(gen_random_uuid(),pg_temp.t(),4,'resume')->>'revision')::int,5,'explicit resume succeeds');
select lives_ok($$update public.task_templates set active=false where id=pg_temp.t()$$,'legacy pause preserved');
select is((select revision from public.task_templates where id=pg_temp.t()),6,'legacy pause advances version');
select is(public.task_routine_history(pg_temp.t())->'rows'->0->>'action','pause','legacy pause audited');
select is(public.task_routine_history(pg_temp.t(),4)->'rows'->0->>'action','archive','history cursor stable');
select throws_ok($$select * from gina.task_routine_changes$$,'42501',null,'raw audit private');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008402","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008402","role":"parent"}}',true);
select throws_ok($$select public.task_routine_history(pg_temp.t())$$,'42501','forbidden','foreign family history blocked');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),6,'resume')$$,'42501','forbidden','foreign family changes blocked');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008401","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008401","role":"device","child_id":"20000000-0000-4000-8000-000000008401"}}',true);
select throws_ok($$select public.task_routine_history(pg_temp.t())$$,'42501','forbidden','child cannot read private edit history');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),6,'resume')$$,'42501','forbidden','child cannot change reward rules');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008401","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008401","role":"parent"}}',true);
select lives_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),6,'resume')$$,'resume before returned-work check');
select lives_ok($$select public.complete_task(pg_temp.t(),current_date+1,gen_random_uuid(),pg_temp.child())$$,'another scheduled occurrence submitted');
select lives_ok($$select public.review_task((select id from public.task_completions where template_id=pg_temp.t() and due_date=current_date+1),false)$$,'return for correction');
select lives_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),7,'save',pg_temp.value(7))$$,'change future stars after returning work');
select lives_ok($$select public.complete_task(pg_temp.t(),current_date+1,gen_random_uuid(),pg_temp.child())$$,'returned work resubmitted');
select is((select task_snapshot->>'stars' from public.task_completions where template_id=pg_temp.t() and due_date=current_date+1),'5','resubmission keeps original promised stars');
select lives_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),8,'save',pg_temp.value(7)||'{"requires_approval":false}')$$,'future work may use automatic approval');
select lives_ok($$select public.complete_task(pg_temp.t(),current_date+2,gen_random_uuid(),pg_temp.child())$$,'automatic approval submission succeeds');
select is((select e.delta from public.star_events e join public.task_completions c on c.id=e.completion_id where c.template_id=pg_temp.t() and c.due_date=current_date+2),7,'automatic approval awards matching snapshot');
select lives_ok($$select public.complete_task('30000000-0000-4000-8000-000000008403',current_date,gen_random_uuid(),'20000000-0000-4000-8000-000000008403')$$,'first automatic task approved without parent review');
select is((select count(*)::int from public.child_badge_awards where child_id='20000000-0000-4000-8000-000000008403' and badge_slug='routine-auto-first'),1,'automatic approval immediately awards first task badge');
select lives_ok($$select public.set_child_archived(gen_random_uuid(),pg_temp.child(),0,true)$$,'profile archive still works');
select throws_ok($$select public.change_task_routine(gen_random_uuid(),pg_temp.t(),10,'resume')$$,'P0001','child_archived','archived profile cannot resume routine');
select lives_ok($$select public.task_routine_history(pg_temp.t())$$,'archived profile history readable');
reset role;
select ok(not has_function_privilege('anon','public.change_task_routine(uuid,uuid,integer,text,jsonb)','execute'),'anonymous mutation denied');
select ok(not has_function_privilege('authenticated','gina.task_completion_snapshot()','execute'),'snapshot trigger private');
select * from finish();rollback;
